import { useEffect, useRef, useState, type FormEvent } from 'react';
import { Link, useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { api, errorMessage } from '../api';
import { useSession } from '../auth';
import { Button, Field, Notice, PageHeader } from '../components';
import { useRecords } from '../hooks';
import { saveDraft, usePrivateDraft } from '../offline';
import type { Page, RecordItem } from '../types';
import { referenceDetailPath, referenceHref, referenceKinds, referenceRoles, type CaseData, type CaseReference, type ReferenceKind, type ReferenceRole } from './case-types';
import './correctionWizard.css';

type Context = {
  regime: 'ams' | 'other' | 'animals' | 'unknown'; filed_on: string | null; national_deadline: string | null;
  first_instalment_on: string | null; check_announced_on: string | null; national_deadline_source: CaseReference | null;
  check_scope: 'affected' | 'unaffected' | 'unknown'; finding_channel: 'ams' | 'administrative' | 'outside_monitoring' | 'unknown';
  non_monitorable_breach: boolean | null; fictional: boolean;
};
type CorrectionData = CaseData & { focused_review_required?: boolean; cap_context?: Context | null; original_statement?: string | null };
type Correction = RecordItem<CorrectionData>;
type RuleSource = { key: string; title: string; url: string; version?: string; article?: string; review_note?: string };
type Guide = { case_id: string; case_revision: number; context: Context; original: { reference: string | null; submitted_at: string | null; statement: string | null; source_pins: CaseReference[] }; evaluation: { status: 'needs_information' | 'ask_authority' | 'may_prepare' | 'restricted' | 'not_covered'; title: string; explanation: string; missing: string[]; restrictions: string[]; deadlines: { national: string | null; eu_latest_possible: string | null; effective: string | null; status: string }; sources: RuleSource[]; rule_version: string; rule_hash: string; fictional: boolean; disclaimer: string }; issues?: { code: string; message: string }[]; notice: string };
type AnswerPin = { kind: ReferenceKind | 'farms'; id: string; revision: number; role?: ReferenceRole };
type Answer = { id: string; label: string; value: unknown; previous_value?: unknown; unit: unknown; period: unknown; source_pins: AnswerPin[]; row_hash: string; checked: boolean; review_kind: 'answer' | 'boundary' };
type Answers = { case_id: string; case_revision: number; fingerprint: string; items: Answer[]; total: number; limit: number; offset: number; next_offset: number | null; checked_count: number; all_checked: boolean };
const emptyContext = (): Context => ({ regime: 'unknown', filed_on: null, national_deadline: null, first_instalment_on: null, check_announced_on: null, national_deadline_source: null, check_scope: 'unknown', finding_channel: 'unknown', non_monitorable_breach: null, fictional: false });
const uuid = /^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i;
const names = ['What did you send?', 'What needs correcting?', 'Check the dates', 'Check each answer', 'Prepare your folder'];
const sourceName = (item: RecordItem) => String(item.data.title || item.data.label || item.data.filename || item.data.name || (item.data.pack_id ? `Prepared report · ${item.data.reporting_year || 'year not recorded'}` : 'Saved record'));
const pinKey = (pin: { kind: string; id: string; role?: ReferenceRole }) => `${pin.kind}/${pin.id}/${pin.role || ''}`;
const editable = (record: Correction) => ['draft', 'needs_changes'].includes(record.data.status);
const dateToday = () => { const now = new Date(); return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`; };
const contextLabels: Record<string, string> = { regime: 'Intervention and monitoring type', filed_on: 'Actual original filing date', national_deadline: 'Applicable national correction deadline', national_deadline_source: 'Source for that national deadline', first_instalment_on: 'First instalment date', check_announced_on: 'Actual on-site check announcement date', check_scope: 'Part affected by the check', finding_channel: 'How the finding was made', non_monitorable_breach: 'Whether the reported condition can be monitored', national_deadline_time_and_timezone: 'The authority’s exact closing time and timezone' };
const text = (value: unknown): string => value === null || value === undefined ? 'Not supplied' : value === '' ? 'Empty text, kept as supplied' : typeof value === 'object' ? JSON.stringify(value, null, 2) : String(value);
const safeOfficial = (value: string) => { try { const url = new URL(value); return url.protocol === 'https:' && !url.username && !url.password ? url.href : null; } catch { return null; } };
async function get<T>(path: string, signal: AbortSignal): Promise<T> { return (await api.downloadResponse(path, { signal })).json() as Promise<T>; }
function checkCase(record: Correction, id: string, workspace: string): Correction {
  if (record.id !== id || record.kind !== 'admin_cases' || record.workspace_id !== workspace || record.data.job_type !== 'correction' || !uuid.test(record.data.farm_id) || !Number.isSafeInteger(record.revision) || record.revision < 1) throw new Error('This link is not a correction case in your current workspace. No other case has been opened.');
  return record;
}
function DraftMessage({ ready, saving, error }: { ready: boolean; saving: boolean; error: string | null }) { return <>{!ready && <p role="status">Opening your private entries…</p>}{saving && <p role="status">Keeping your private entries on this device…</p>}{error && <Notice kind="warning">{error} Keep this page open until you can save your work.</Notice>}</>; }
function SourceLinks({ pins, farmId }: { pins: Answer['source_pins']; farmId: string }) { return <ul className="correction-source-links">{pins.map(pin => <li key={`${pinKey(pin)}/${pin.revision}`}><Link to={pin.kind === 'farms' ? `/app/fields/${pin.id}` : referenceHref({ ...pin, kind: pin.kind }, farmId)}>Read {pin.kind === 'farms' ? 'farm details' : referenceKinds.find(kind => kind.value === pin.kind)?.label.toLowerCase() || 'saved source'}</Link>{pin.role && <> · {referenceRoles.find(role => role.value === pin.role)?.label}</>}<details><summary>Saved version details</summary><p>{pin.id} · version {pin.revision}</p></details></li>)}</ul>; }

function Sources({ farmId, references, onChange, role: initialRole, disabled = false }: { farmId: string; references: CaseReference[]; onChange: (pins: CaseReference[]) => void; role: ReferenceRole; disabled?: boolean }) {
  const { session } = useSession(); const [kind, setKind] = useState<ReferenceKind>('documents'); const [role, setRole] = useState(initialRole); const [offset, setOffset] = useState(0); const [refresh, setRefresh] = useState(0);
  const [state, setState] = useState<{ key: string; page?: Page; error?: string }>({ key: '' });
  const key = `${session?.workspace.id}/${farmId}/${kind}/${offset}/${refresh}`; const current = state.key === key ? state : null;
  useEffect(() => {
    if (!farmId || disabled) return; const controller = new AbortController(); let active = true;
    const path = kind === 'field_change_proposals' ? `/farms/${farmId}/field-proposals?` : `/${kind}?farm_id=${farmId}&${kind === 'reports' ? 'view=summary&' : ''}`;
    void get<Page>(`${path}limit=10&offset=${offset}`, controller.signal).then(page => { if (!Array.isArray(page.items) || page.offset !== offset || page.limit !== 10 || !Number.isSafeInteger(page.total) || page.total < 0 || page.items.length > 10 || page.items.some(item => item.workspace_id !== session?.workspace.id || item.data.farm_id !== farmId || !uuid.test(item.id) || !Number.isInteger(item.revision) || item.revision < 1)) throw new Error('This page does not match the chosen farm. Retry before choosing a record.'); if (active) setState({ key, page }); }).catch(reason => { if (active && !controller.signal.aborted) setState({ key, error: errorMessage(reason) }); });
    return () => { active = false; controller.abort(); };
  }, [key, disabled]);
  return <details className="correction-sources"><summary>{initialRole === 'original' ? 'Choose the original record, if it is saved here' : 'Choose corrected records and supporting evidence'}</summary><p>Only this farm’s records are offered. A prepared report is not a receipt or proof of sending. Selecting a field change does not update official records.</p>
    {!!references.length && <ul>{references.map(pin => <li key={pinKey(pin)}>{referenceRoles.find(item => item.value === pin.role)?.label}: <Link to={referenceHref(pin, farmId)}>Read selected {referenceKinds.find(item => item.value === pin.kind)?.label.toLowerCase()}</Link>{!disabled && <Button variant="ghost" onClick={() => onChange(references.filter(item => pinKey(item) !== pinKey(pin)))}>Remove this choice</Button>}<details><summary>Saved version details</summary><p>{pin.id} · version {pin.revision}</p></details></li>)}</ul>}
    {!disabled && <><div className="form-grid"><Field label="Find a saved record"><select value={kind} onChange={event => { setKind(event.target.value as ReferenceKind); setOffset(0); }}>{referenceKinds.map(item => <option key={item.value} value={item.value}>{item.label}</option>)}</select></Field><Field label="Use this record as"><select value={role} onChange={event => setRole(event.target.value as ReferenceRole)}>{(initialRole === 'original' ? referenceRoles.filter(item => ['original', 'notice'].includes(item.value)) : referenceRoles.filter(item => item.value !== 'original')).map(item => <option key={item.value} value={item.value}>{item.label}</option>)}</select></Field></div>
      {current?.error ? <Notice kind="error">{current.error}<Button variant="secondary" onClick={() => setRefresh(value => value + 1)}>Retry saved records</Button></Notice> : !current?.page ? <p role="status">Opening saved records for this farm…</p> : current.page.items.length ? <ul className="record-list">{current.page.items.map(item => { const chosen = references.find(pin => pin.id === item.id && pin.kind === kind && pin.role === role); return <li key={item.id}><div><strong>{sourceName(item)}</strong><p>{kind === 'reports' ? item.data.status === 'issued' ? 'Approved inside the app; actual sending must still be recorded separately.' : 'Draft report; separate approval is still needed.' : text(item.data.review_status || item.data.status || 'Saved record')}</p><Link to={referenceHref({ kind, id: item.id, revision: item.revision }, farmId)}>Read this record</Link>{chosen && chosen.revision !== item.revision && <Notice kind="warning">This choice changed. Remove it, read the current record and explicitly choose it again.</Notice>}</div><Button variant="secondary" disabled={!!chosen || references.length >= 100} onClick={() => onChange([...references, { kind, id: item.id, revision: item.revision, role }])}>Choose this record</Button></li>; })}</ul> : <p>No records are on this page. This does not mean you need no evidence.</p>}
      <div className="actions"><Button variant="secondary" disabled={offset === 0} onClick={() => setOffset(value => Math.max(0, value - 10))}>Previous records</Button><span>{current?.page ? `${Math.min(offset + 1, current.page.total)}–${offset + current.page.items.length} of ${current.page.total}` : 'Page unavailable'}</span><Button variant="secondary" disabled={!current?.page || offset + current.page.items.length >= current.page.total} onClick={() => setOffset(value => value + 10)}>Next records</Button><Button variant="ghost" onClick={() => setRefresh(value => value + 1)}>Refresh records</Button></div><p><Link to={`/app/documents?farm_id=${farmId}`}>Add the actual original or supporting document</Link></p>
    </>}
  </details>;
}

type OriginalDraft = { attempt: string; farmId: string; year: string; title: string; reference: string; date: string; statement: string; references: CaseReference[] };
export function NewCorrectionWizard() {
  const { session } = useSession(); const [params] = useSearchParams();
  return session ? <StartCorrection key={`${session.user.id}/${session.workspace.id}/${params.toString()}`} /> : null;
}
function StartCorrection() {
  const { session } = useSession(); const farms = useRecords('farms'); const navigate = useNavigate(); const [params] = useSearchParams();
  const initial = useRef<OriginalDraft>({ attempt: crypto.randomUUID(), farmId: params.get('farm_id') || '', year: params.get('reporting_year') || '', title: 'Correction to my submitted application', reference: '', date: '', statement: '', references: [] });
  const draftName = `correction/new/${params.get('farm_id') || 'choose'}/${params.get('reference_id') || 'blank'}`; const draft = usePrivateDraft(draftName, initial.current);
  const [ack, setAck] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [seedMessage, setSeedMessage] = useState(''); const [seedRetry, setSeedRetry] = useState(0); const [seed, setSeed] = useState<{ pin: CaseReference; title: string } | null>(null);
  const request = useRef<AbortController | null>(null); const mounted = useRef(true); const value = draft.value;
  const canWrite = session?.workspace.role === 'owner' || session?.workspace.role === 'adviser' && session.workspace.permissions?.includes('review') === true;
  useEffect(() => { mounted.current = true; const reset = () => setAck(false); window.addEventListener('focus', reset); window.addEventListener('online', reset); return () => { mounted.current = false; request.current?.abort(); window.removeEventListener('focus', reset); window.removeEventListener('online', reset); }; }, []);
  useEffect(() => {
    if (!draft.ready || !params.get('reference_id')) return; const controller = new AbortController(); let active = true; setSeed(null);
    const id = params.get('reference_id')!; const kind = params.get('reference_kind') as ReferenceKind; const role = params.get('reference_role') as ReferenceRole; const revision = Number(params.get('reference_revision'));
    if (!uuid.test(id) || !referenceKinds.some(item => item.value === kind) || !referenceRoles.some(item => item.value === role) || !Number.isSafeInteger(revision) || revision < 1 || value.farmId !== params.get('farm_id') || ['reference_id', 'reference_kind', 'reference_revision', 'reference_role'].some(key => params.getAll(key).length !== 1)) { setSeedMessage('This linked source could not be matched to this farm. Choose the actual original below; another record has not been substituted.'); return; }
    setSeedMessage('Checking the linked saved record…'); void get<RecordItem>(referenceDetailPath({ kind, id }), controller.signal).then(record => { if (record.id !== id || record.workspace_id !== session?.workspace.id || record.data.farm_id !== value.farmId || record.revision !== revision) throw new Error('The linked source changed or does not match this farm. Open it and choose the actual current record below.'); if (active) { setSeed({ pin: { kind, id, revision, role }, title: sourceName(record) }); setSeedMessage('Read the linked record, then explicitly include it only if it belongs in this correction. It is not proof of sending.'); } }).catch(reason => { if (active && !controller.signal.aborted) setSeedMessage(errorMessage(reason)); });
    return () => { active = false; controller.abort(); };
  }, [draft.ready, value.farmId, seedRetry]);
  function edit(update: Partial<OriginalDraft>) { draft.setValue(previous => ({ ...previous, ...update, attempt: crypto.randomUUID() })); setAck(false); setError(''); }
  async function save(event: FormEvent) {
    event.preventDefault(); if (!session || !canWrite || !draft.ready || !ack || busy) return; const controller = new AbortController(); request.current = controller; setBusy(true); setError('');
    try { if (!value.reference.trim() && !value.references.some(pin => pin.role === 'original')) throw new Error('Record the original reference or choose its actual saved original. Do not invent a reference.'); if (!value.statement.trim()) throw new Error('Describe what you actually sent. A prepared report is not proof that it was sent.'); await saveDraft(`${session.user.id}/${session.workspace.id}`, draftName, value); if (!mounted.current || controller.signal.aborted) return;
      const saved = await api.post<Correction>('/cases', { farm_id: value.farmId, job_type: 'correction', reporting_year: Number(value.year), title: value.title, original_reference: value.reference || null, original_submitted_at: value.date || null, original_statement: value.statement, references: value.references, focused_review_required: true, cap_context: { ...emptyContext(), filed_on: value.date || null } }, { idempotencyKey: value.attempt, signal: controller.signal }); checkCase(saved, saved.id, session.workspace.id); if (saved.data.farm_id !== value.farmId) throw new Error('The saved correction does not match this farm. Your private entries remain here.'); if (!mounted.current || controller.signal.aborted) return; await draft.clear(); if (mounted.current) navigate(`/app/cases/${saved.id}/correction?step=2`);
    } catch (reason) { if (mounted.current && !controller.signal.aborted) { setError(errorMessage(reason)); setAck(false); } } finally { if (mounted.current) setBusy(false); }
  }
  return <><PageHeader title="Correct something you already sent" description="Start with the original. We will keep it separate from the correction you prepare." /><Link to="/app/cases">Back to Paperwork cases</Link><section className="card correction-wizard"><p className="eyebrow">Step 1 of 5</p><h2>What did you send?</h2><Notice>Nothing here changes or sends an official application. You can keep preparing while a date or correction route is unknown.</Notice><DraftMessage {...draft} />{error && <Notice kind="error">{error}</Notice>}{!canWrite && <Notice>Your current access is read-only. Ask the farm owner or a delegated reviewer to start this correction.</Notice>}
    <form onSubmit={save} className="stack"><fieldset disabled={!canWrite || !draft.ready || busy}><div className="form-grid"><Field label="Farm"><select required value={value.farmId} onChange={event => edit({ farmId: event.target.value, references: [] })}><option value="">Choose the farm</option>{farms.items.map(farm => <option key={farm.id} value={farm.id}>{sourceName(farm)}</option>)}</select></Field><Field label="Application year"><input required type="number" min="1900" max="2200" value={value.year} onChange={event => edit({ year: event.target.value })} /></Field><Field label="Name this correction"><input required maxLength={240} value={value.title} onChange={event => edit({ title: event.target.value })} /></Field><Field label="Original submission reference, if known"><input maxLength={240} value={value.reference} onChange={event => edit({ reference: event.target.value })} /></Field><Field label="Date you actually sent the original, if known" hint="Leave this empty if you do not know. This actual date is also used in the date guidance."><input type="date" max={dateToday()} value={value.date} onChange={event => edit({ date: event.target.value })} /></Field><Field label="What did you actually send?"><textarea required maxLength={4000} value={value.statement} onChange={event => edit({ statement: event.target.value })} /></Field></div>
      {farms.loading && <p role="status">Opening your permitted farms…</p>}{farms.error && <Notice kind="error">{farms.error}<Button variant="secondary" onClick={() => void farms.reload()}>Retry farms</Button></Notice>}
      {seedMessage && <Notice>{seedMessage}{seed && <><p>{seed.title} · {referenceRoles.find(role => role.value === seed.pin.role)?.label}</p><Link to={referenceHref(seed.pin, value.farmId)}>Read linked source</Link><Button variant="secondary" disabled={value.references.some(pin => pinKey(pin) === pinKey(seed.pin)) || value.references.length >= 100} onClick={() => edit({ references: [...value.references, seed.pin] })}>Include this linked record</Button></>}<Button variant="ghost" onClick={() => setSeedRetry(value => value + 1)}>Check linked source again</Button></Notice>}
      {value.farmId && <Sources farmId={value.farmId} role="original" references={value.references} onChange={references => edit({ references })} />}
      <label className="check-row"><input type="checkbox" checked={ack} onChange={event => setAck(event.target.checked)} />I have described an original I actually sent. A saved or approved app report alone does not establish that it was sent.</label><Button type="submit" loading={busy} disabled={!ack || !value.farmId || !value.year}>Save original and continue</Button></fieldset></form>
  </section></>;
}

type DetailsDraft = { attempt: string; base: number; title: string; authority: string; scheme: string; originalReference: string; originalDate: string; statement: string; reason: string; references: CaseReference[]; context: Context };
const detailsValue = (record: Correction): DetailsDraft => ({ attempt: crypto.randomUUID(), base: record.revision, title: record.data.title, authority: record.data.authority || '', scheme: record.data.scheme || '', originalReference: record.data.original_reference || '', originalDate: record.data.original_submitted_at || '', statement: record.data.original_statement || '', reason: record.data.reason || '', references: record.data.references, context: { ...emptyContext(), ...record.data.cap_context } });
function DetailsStep({ record, step, canWrite, onSaved, onNext }: { record: Correction; step: number; canWrite: boolean; onSaved: (record: Correction) => void; onNext: () => void }) {
  const { session } = useSession(); const draftName = `correction/${record.id}/details`; const draft = usePrivateDraft(draftName, detailsValue(record)); const value = draft.value;
  const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [ack, setAck] = useState(false); const mounted = useRef(true); const request = useRef<AbortController | null>(null); const stale = value.base !== record.revision;
  const currentRevision = useRef(record.revision); currentRevision.current = record.revision;
  useEffect(() => { mounted.current = true; const reset = () => setAck(false); window.addEventListener('focus', reset); window.addEventListener('online', reset); return () => { mounted.current = false; request.current?.abort(); window.removeEventListener('focus', reset); window.removeEventListener('online', reset); }; }, []);
  function edit(update: Partial<DetailsDraft>) { draft.setValue(previous => ({ ...previous, ...update, attempt: crypto.randomUUID() })); setAck(false); setError(''); }
  function context(update: Partial<Context>) {
    if (update.national_deadline_source && !['original', 'notice'].includes(update.national_deadline_source.role)) { setAck(false); setError('The national deadline must come from a record explicitly selected as an original or notice. Choose its actual source under “What needs correcting?”, with the role “Letter or inspection notice”, then select it here.'); return; }
    edit({ context: { ...value.context, ...update } });
  }
  async function save(event: FormEvent) {
    event.preventDefault(); if (!session || !canWrite || !draft.ready || busy || stale || !ack) return; setBusy(true); setError(''); const captured = value; const controller = new AbortController(); request.current = controller;
    try { if (!captured.statement.trim()) throw new Error('First describe what you actually sent in “What did you send?”. A prepared report alone is not a recorded original filing.'); await saveDraft(`${session.user.id}/${session.workspace.id}`, draftName, captured); if (!mounted.current || controller.signal.aborted || currentRevision.current !== captured.base) return; const saved = await api.patch<Correction>(`/cases/${record.id}`, { expected_revision: captured.base, data: { title: captured.title, authority: captured.authority || null, scheme: captured.scheme || null, original_reference: captured.originalReference || null, original_submitted_at: captured.originalDate || null, original_statement: captured.statement || null, reason: captured.reason || null, references: captured.references, cap_context: captured.context, focused_review_required: true } }, { idempotencyKey: `${captured.attempt}:${captured.base}`, signal: controller.signal }); checkCase(saved, record.id, session.workspace.id); if (saved.data.farm_id !== record.data.farm_id) throw new Error('The returned case belongs to another farm. Your private entries are retained.'); if (!mounted.current || controller.signal.aborted || currentRevision.current !== captured.base) return; draft.setValue(detailsValue(saved)); setAck(false); onSaved(saved); onNext(); }
    catch (reason) { if (mounted.current && !controller.signal.aborted) { setError(errorMessage(reason)); setAck(false); } } finally { if (mounted.current) setBusy(false); }
  }
  return <section className="card"><h2>{names[step]}</h2><DraftMessage {...draft} />{error && <Notice kind="error">{error} Your private entries are retained. Reload the saved case before retrying a changed version.</Notice>}
    {stale && <Notice kind="warning"><p>The saved case changed. Compare it before keeping or replacing your private entries.</p><details open><summary>Current saved details</summary><dl>{[['Name', record.data.title], ['Authority', record.data.authority], ['Scheme', record.data.scheme], ['Original reference', record.data.original_reference], ['Original date', record.data.original_submitted_at], ['Original statement', record.data.original_statement], ['Correction explanation', record.data.reason]].map(([label, content]) => <div key={String(label)}><dt>{label}</dt><dd>{text(content)}</dd></div>)}</dl><h3>Current source choices</h3><SourceLinks farmId={record.data.farm_id} pins={record.data.references} /><h3>Current date and check context</h3><dl>{Object.entries(record.data.cap_context || emptyContext()).map(([key, content]) => <div key={key}><dt>{contextLabels[key] || key.replaceAll('_', ' ')}</dt><dd><pre>{text(content)}</pre></dd></div>)}</dl></details><Button variant="secondary" disabled={!canWrite || busy} onClick={() => edit({ base: record.revision })}>Keep my entries after comparing the saved case</Button><Button variant="secondary" disabled={!canWrite || busy} onClick={() => { draft.setValue(detailsValue(record)); setAck(false); }}>Replace my private entries with the saved case</Button></Notice>}
    <form onSubmit={save} className="stack"><fieldset disabled={!canWrite || !editable(record) || !draft.ready || busy || stale}>
      {step === 0 ? <><p>The original stays separate from the correction. Enter only actual sending details; leave an unknown date empty.</p><Field label="Original submission reference, if known"><input maxLength={240} value={value.originalReference} onChange={event => edit({ originalReference: event.target.value })} /></Field><Field label="Date you actually sent the original, if known" hint="This actual date is also used in the date guidance."><input type="date" max={dateToday()} value={value.originalDate} onChange={event => edit({ originalDate: event.target.value, context: { ...value.context, filed_on: event.target.value || null } })} /></Field><Field label="What did you actually send?"><textarea maxLength={4000} value={value.statement} onChange={event => edit({ statement: event.target.value })} /></Field><Sources farmId={record.data.farm_id} references={value.references} onChange={references => edit({ references })} role="original" /></> : step === 1 ? <><p>Explain the mistake in plain words. Choose the corrected saved records, not a replacement for the original history. Old and proposed values will be read back in “Check each answer”.</p><Field label="What is wrong, and what should change?"><textarea required maxLength={4000} value={value.reason} onChange={event => edit({ reason: event.target.value })} /></Field><div className="form-grid"><Field label="Authority or recipient, if known"><input maxLength={240} value={value.authority} onChange={event => edit({ authority: event.target.value })} /></Field><Field label="Application or scheme, if known"><input maxLength={240} value={value.scheme} onChange={event => edit({ scheme: event.target.value })} /></Field></div><Sources farmId={record.data.farm_id} references={value.references} onChange={references => edit({ references })} role="change" /><p>Change a wrong farm answer, work record, report or field proposal in its own screen first. Its separate confirmation or approval is still required.</p></> : <><p>Use the actual authority instructions and notices. Unknown is a valid answer; it does not grant permission to amend. Saving these details does not change the original sending record.</p><div className="form-grid"><Field label="Which intervention or monitoring route applies?"><select value={value.context.regime} onChange={event => context({ regime: event.target.value as Context['regime'] })}><option value="unknown">I do not know</option><option value="ams">The intervention is covered by the area monitoring system (AMS)</option><option value="other">Another area intervention, not covered by AMS</option><option value="animals">An animal intervention — separate rules need checking</option></select></Field><Field label="Actual original filing date, if known"><input type="date" max={dateToday()} value={value.context.filed_on || ''} onChange={event => context({ filed_on: event.target.value || null })} /></Field><Field label="National correction deadline stated in the applicable instructions"><input type="date" value={value.context.national_deadline || ''} onChange={event => context({ national_deadline: event.target.value || null })} /></Field><Field label="Saved source for that national deadline" hint="Selecting a source does not independently verify the legal deadline."><select value={value.context.national_deadline_source ? pinKey(value.context.national_deadline_source) : ''} onChange={event => context({ national_deadline_source: value.references.find(pin => pinKey(pin) === event.target.value) || null })}><option value="">Not established — choose the actual source record first</option>{value.references.map((pin, index) => <option key={pinKey(pin)} value={pinKey(pin)}>Selected record {index + 1}: {referenceKinds.find(kind => kind.value === pin.kind)?.label} · {referenceRoles.find(role => role.value === pin.role)?.label}</option>)}</select></Field><Field label="First instalment date, if specifically established" hint="Do not enter a generic payment date or an expected payment."><input type="date" value={value.context.first_instalment_on || ''} onChange={event => context({ first_instalment_on: event.target.value || null })} /></Field><Field label="Date an intended on-site check was actually announced, if any"><input type="date" max={dateToday()} value={value.context.check_announced_on || ''} onChange={event => context({ check_announced_on: event.target.value || null })} /></Field><Field label="Which part does the check concern?"><select value={value.context.check_scope} onChange={event => context({ check_scope: event.target.value as Context['check_scope'] })}><option value="unknown">Not established</option><option value="affected">The part I want to change is affected</option><option value="unaffected">The proposed change concerns an unaffected part, with actual scope evidence</option></select></Field><Field label="How was the finding made?"><select value={value.context.finding_channel} onChange={event => context({ finding_channel: event.target.value as Context['finding_channel'] })}><option value="unknown">Not established</option><option value="ams">Area monitoring system (AMS)</option><option value="administrative">Administrative check</option><option value="outside_monitoring">Outside AMS or administrative checks</option></select></Field><Field label="Is the reported breach about a condition that cannot be monitored by AMS?"><select value={value.context.non_monitorable_breach === null ? 'unknown' : String(value.context.non_monitorable_breach)} onChange={event => context({ non_monitorable_breach: event.target.value === 'unknown' ? null : event.target.value === 'true' })}><option value="unknown">Not established</option><option value="true">Yes, established from the actual finding</option><option value="false">No, established from the actual finding</option></select></Field></div><p>An unannounced check, the actual affected scope and other national conditions may need separate authority advice. A blank notice date does not prove that there is no restriction.</p></>}
      <label className="check-row"><input type="checkbox" checked={ack} onChange={event => setAck(event.target.checked)} />I checked these entries against my records. Unknown details have not been guessed.</label><Button type="submit" loading={busy} disabled={!ack}>Save this step and continue</Button><p>Saving changed information invalidates earlier answer checks and sending review. Nothing is sent.</p>
    </fieldset></form>{(!canWrite || !editable(record)) && <><Notice>This case is read-only at its current stage. Read the saved records, or use the full case to explicitly reopen preparation. Earlier sending records remain unchanged.</Notice><Link to={`/app/cases/${record.id}`}>Open the full case and its history</Link></>}
  </section>;
}

function Guidance({ guide }: { guide: Guide }) {
  const value = guide.evaluation;
  return <section className="correction-guidance"><h3>Can I still change this?</h3><Notice kind={value.status === 'may_prepare' ? 'info' : 'warning'}><strong>{value.title}</strong><p>{value.explanation}</p></Notice>{value.fictional && <Notice kind="warning">Fictional example. These dates and records are not your actual application.</Notice>}
    {guide.issues?.map(issue => <Notice kind="warning" key={issue.code}>{issue.message}</Notice>)}
    {!!value.missing.length && <><h4>Still to establish</h4><ul>{value.missing.map(key => <li key={key}>{contextLabels[key] || key.replaceAll('_', ' ')}</li>)}</ul></>}{!!value.restrictions.length && <><h4>Conditions to check with the authority or adviser</h4><ul>{value.restrictions.map((message, index) => <li key={index}>{message}</li>)}</ul></>}
    <dl className="detail-grid"><div><dt>National date you supplied</dt><dd>{value.deadlines.national || 'Unknown'}</dd></div><div><dt>EU latest possible date from the supplied first instalment</dt><dd>{value.deadlines.eu_latest_possible || 'Cannot be established'}<p>This is not a substitute for an earlier national deadline.</p></dd></div><div><dt>Source-linked date considered by this guide</dt><dd>{value.deadlines.effective || 'Not established'}<p>A source link is not independent legal verification.</p></dd></div></dl>
    <p>{value.disclaimer}</p><details><summary>Read the rules and their limits</summary><ul>{value.sources.map(source => { const href = safeOfficial(source.url); return <li key={source.key}>{href ? <a href={href} target="_blank" rel="noopener noreferrer">{source.title}</a> : source.title}<p>{source.article} {source.version}</p>{source.review_note && <p>{source.review_note}</p>}</li>; })}</ul><p>Rule edition: {value.rule_version}</p></details>
  </section>;
}

function BoundaryReadback({ before, after }: { before?: unknown; after: unknown }) {
  type Polygon = { label: string; rings: number[][][] };
  function polygons(value: unknown): Polygon[] { if (!value || typeof value !== 'object') return []; const parcels = (value as { parcels?: unknown }).parcels; if (!Array.isArray(parcels)) return []; return parcels.flatMap((parcel: Record<string, any>) => { const geometry = parcel?.geometry; if (!Array.isArray(geometry?.coordinates)) return []; const rings = geometry.type === 'Polygon' ? geometry.coordinates : geometry.type === 'MultiPolygon' ? geometry.coordinates.flat() : null; if (!Array.isArray(rings) || !rings.length || rings.some((ring: unknown) => !Array.isArray(ring) || ring.length < 4 || ring.some(point => !Array.isArray(point) || point.length < 2 || !Number.isFinite(point[0]) || !Number.isFinite(point[1])))) return []; return [{ label: String(parcel.name || 'Saved field'), rings }]; }); }
  const old = polygons(before); const current = polygons(after); const points = [...old, ...current].flatMap(polygon => polygon.rings.flat());
  if (!points.length) return <p>No drawable outline was supplied here. Open the exact saved field proposal to compare all of its geometry before checking this answer.</p>;
  const bounds = points.reduce((box, point) => ({ minX: Math.min(box.minX, point[0]), minY: Math.min(box.minY, point[1]), maxX: Math.max(box.maxX, point[0]), maxY: Math.max(box.maxY, point[1]) }), { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity }); const { minX, minY } = bounds; const width = bounds.maxX - minX || 0.0001; const height = bounds.maxY - minY || 0.0001; const scale = Math.min(440 / width, 220 / height);
  const path = (polygon: Polygon) => polygon.rings.map(ring => ring.map((point, index) => `${index ? 'L' : 'M'}${30 + (point[0] - minX) * scale},${250 - (point[1] - minY) * scale}`).join(' ') + ' Z').join(' ');
  return <figure className="correction-boundary"><svg viewBox="0 0 500 280" role="img" aria-label="Supplied original and selected saved field outlines; not a survey or eligibility map">{old.map((polygon, index) => <path key={`old-${index}`} d={path(polygon)} fill="none" stroke="#766f68" strokeWidth="3" strokeDasharray="7 5" fillRule="evenodd"><title>Original: {polygon.label}</title></path>)}{current.map((polygon, index) => <path key={`new-${index}`} d={path(polygon)} fill="#64334b20" stroke="#64334b" strokeWidth="2" fillRule="evenodd"><title>Selected saved outline: {polygon.label}</title></path>)}</svg><figcaption>Dashed grey: supplied original. Plum: selected saved outline. {old.length ? '' : 'No authoritative original outline was supplied.'} Coordinates are shown only for comparison; no area, entitlement or official acceptance is calculated.</figcaption></figure>;
}

function AnswerValues({ row }: { row: Answer }) {
  if (row.source_pins.length && row.source_pins.every(pin => pin.role === 'original')) return <div><h4>Value retained in the selected original</h4><pre>{text(row.value)}</pre><p>This remains original evidence. It has not been relabelled as the proposed replacement. Compare it with the separately selected corrected record.</p></div>;
  return <div className="correction-value-pair"><div><h4>Original saved value</h4><pre>{Object.hasOwn(row, 'previous_value') ? text(row.previous_value) : 'No authoritative original value was supplied. Do not assume this was blank or zero.'}</pre></div><div><h4>Current saved answer being reviewed</h4><pre>{text(row.value)}</pre></div></div>;
}

function AnswerReview({ record, canWrite, onSaved, reload }: { record: Correction; canWrite: boolean; onSaved: (record: Correction) => void; reload: () => void }) {
  const { session } = useSession(); const [offset, setOffset] = useState(0); const [refresh, setRefresh] = useState(0); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const [state, setState] = useState<{ key: string; page?: Answers; error?: string }>({ key: '' }); const controller = useRef<AbortController | null>(null); const mounted = useRef(true);
  const draftName = `correction/${record.id}/answer-checks`; const draft = usePrivateDraft<{ attempt: string; fingerprint: string; ids: string[] }>(draftName, { attempt: crypto.randomUUID(), fingerprint: '', ids: [] });
  const key = `${record.id}/${record.revision}/${offset}/${refresh}`; const page = state.key === key ? state.page : undefined; const pageError = state.key === key ? state.error : undefined;
  useEffect(() => { mounted.current = true; return () => { mounted.current = false; controller.current?.abort(); }; }, []);
  useEffect(() => { const request = new AbortController(); let active = true; void get<Answers>(`/cases/${record.id}/answer-review?limit=5&offset=${offset}`, request.signal).then(value => { if (value.case_id !== record.id || !Number.isInteger(value.case_revision) || value.case_revision !== record.revision || !/^[a-f0-9]{64}$/.test(value.fingerprint) || !Array.isArray(value.items) || value.items.length > 5 || value.offset !== offset || value.limit !== 5 || !Number.isSafeInteger(value.total) || value.total < 0 || value.items.some(row => !row.id || !/^[a-f0-9]{64}$/.test(row.row_hash) || !Array.isArray(row.source_pins) || typeof row.checked !== 'boolean') || value.next_offset !== null && (!Number.isSafeInteger(value.next_offset) || value.next_offset <= offset)) throw new Error('The saved answer review changed or this page is incomplete. Reload the saved case; no answers have been marked checked.'); if (active) setState({ key, page: value }); }).catch(reason => { if (active && !request.signal.aborted) setState({ key, error: errorMessage(reason) }); }); return () => { active = false; request.abort(); }; }, [key]);
  const stale = !!page && !!draft.value.fingerprint && draft.value.fingerprint !== page.fingerprint; const ids = page?.items.filter(row => !row.checked && draft.value.ids.includes(row.id)).map(row => row.id) || [];
  function choose(id: string, checked: boolean) { if (!page || stale) return; draft.setValue(previous => ({ attempt: crypto.randomUUID(), fingerprint: page.fingerprint, ids: checked ? [...new Set([...previous.ids, id])] : previous.ids.filter(value => value !== id) })); setError(''); }
  async function save() {
    if (!session || !canWrite || !editable(record) || !page || !draft.ready || stale || !ids.length || busy) return; const request = new AbortController(); controller.current = request; setBusy(true); setError('');
    try { await saveDraft(`${session.user.id}/${session.workspace.id}`, draftName, draft.value); if (!mounted.current || request.signal.aborted) return; const result = await api.post<{ case: Correction; answer_review: Answers }>(`/cases/${record.id}/answer-review`, { expected_revision: record.revision, fingerprint: page.fingerprint, checked_ids: ids }, { idempotencyKey: `${draft.value.attempt}:${record.revision}`, signal: request.signal }); checkCase(result.case, record.id, session.workspace.id); if (result.case.data.farm_id !== record.data.farm_id) throw new Error('The saved answer check belongs to another farm. Reload before retrying.'); if (!mounted.current || request.signal.aborted) return; draft.setValue(previous => ({ ...previous, attempt: crypto.randomUUID(), ids: previous.ids.filter(id => !ids.includes(id)) })); onSaved(result.case); setRefresh(value => value + 1); }
    catch (reason) { if (mounted.current && !request.signal.aborted) setError(errorMessage(reason)); } finally { if (mounted.current) setBusy(false); }
  }
  return <section className="card"><h2>Check each answer</h2><p>Read every answer, including values carried forward from your saved records. Check it only after comparing the actual source. Checking an answer records your review; it does not change that source or prove eligibility.</p><DraftMessage {...draft} />{error && <Notice kind="error">{error} Your private choices are retained. Refresh the saved case and compare changed sources.</Notice>}
    {pageError ? <Notice kind="error">{pageError}<Button variant="secondary" onClick={reload}>Reload saved case</Button><Button variant="secondary" onClick={() => setRefresh(value => value + 1)}>Retry answer page</Button></Notice> : !page ? <p role="status">Opening the saved answers and their sources…</p> : <><p>{page.checked_count} of {page.total} answers checked against this saved version.</p>{page.all_checked && page.total > 0 ? <Notice kind="success">Every applicable answer in this saved version has a human check. Final case review is still separate.</Notice> : !page.total ? <Notice kind="warning">No applicable answers are available. This is not a completed review. Choose the actual original and corrected records first.</Notice> : null}
      {stale && <Notice kind="warning">The answers or sources changed. Your private choices were kept, but none will be reused as checks for this version.<Button variant="secondary" disabled={!canWrite || busy} onClick={() => draft.setValue({ attempt: crypto.randomUUID(), fingerprint: page.fingerprint, ids: [] })}>Start checking this changed version</Button></Notice>}
      {page.items.map(row => <article className="correction-answer" key={`${row.id}/${row.row_hash}`}><h3>{row.label}</h3>{row.review_kind === 'boundary' ? <BoundaryReadback before={row.previous_value} after={row.value} /> : <AnswerValues row={row} />}<p>Unit: {text(row.unit)} · Period: {text(row.period)}</p><SourceLinks pins={row.source_pins} farmId={record.data.farm_id} />{row.review_kind === 'boundary' && <details><summary>Read all supplied field details</summary><pre>{text({ original: Object.hasOwn(row, 'previous_value') ? row.previous_value : 'Not supplied', selected: row.value })}</pre></details>}<label className="check-row"><input type="checkbox" checked={row.checked || !stale && draft.value.ids.includes(row.id)} disabled={row.checked || !canWrite || !editable(record) || !draft.ready || busy || stale} onChange={event => choose(row.id, event.target.checked)} />{row.checked ? 'Checked by a person for this saved version' : row.review_kind === 'boundary' ? 'I compared this whole field change and its sources.' : 'I checked this answer, its unit, period and sources.'}</label></article>)}
      {canWrite && editable(record) && <Button loading={busy} disabled={!ids.length || stale || !draft.ready} onClick={() => void save()}>Save these answer checks</Button>}
    </>}
    <div className="actions"><Button variant="secondary" disabled={offset === 0 || busy} onClick={() => setOffset(value => Math.max(0, value - 5))}>Previous answers</Button><span>{page ? `${Math.min(offset + 1, page.total)}–${offset + page.items.length} of ${page.total}` : 'Page unavailable'}</span><Button variant="secondary" disabled={!page || page.next_offset === null || busy} onClick={() => { if (page?.next_offset !== null && page?.next_offset !== undefined) setOffset(page.next_offset); }}>Next answers</Button></div><p>Only individually selected answers on this page are saved by the button. Moving to another page does not mark anything checked.</p>
  </section>;
}

export function CorrectionWizardPage() {
  const { session } = useSession(); const { id } = useParams();
  return session ? <CorrectionJourney key={`${session.user.id}/${session.workspace.id}/${session.workspace.role}/${JSON.stringify(session.workspace.permissions)}/${JSON.stringify(session.workspace.farm_ids)}/${id}`} id={id || ''} /> : null;
}
function CorrectionJourney({ id }: { id: string }) {
  const { session } = useSession(); const [params, setParams] = useSearchParams(); const parsed = Number(params.get('step')); const step = Number.isInteger(parsed) && parsed >= 1 && parsed <= 5 ? parsed - 1 : 0;
  const [record, setRecord] = useState<Correction | null>(null); const [guide, setGuide] = useState<Guide | null>(null); const [error, setError] = useState(''); const [guideError, setGuideError] = useState(''); const [refresh, setRefresh] = useState(0); const [loading, setLoading] = useState(true);
  const canWrite = session?.workspace.role === 'owner' || session?.workspace.role === 'adviser' && session.workspace.permissions?.includes('review') === true;
  useEffect(() => {
    if (!session) return; const controller = new AbortController(); let active = true; setLoading(true); setError(''); setGuide(null); setGuideError('');
    async function load() { if (!uuid.test(id)) throw new Error('This correction link is invalid. Open the actual case from Paperwork.'); const value = checkCase(await get<Correction>(`/cases/${id}`, controller.signal), id, session!.workspace.id); if (!active) return; setRecord(value);
      try { const next = await get<Guide>(`/cases/${id}/correction-guide`, controller.signal); if (next.case_id !== id || next.case_revision !== value.revision || !next.evaluation || !Array.isArray(next.evaluation.sources) || !Array.isArray(next.evaluation.missing) || !Array.isArray(next.evaluation.restrictions)) throw new Error('The correction guidance changed while loading. Reload the saved case.'); if (active) setGuide(next); } catch (reason) { if (active && !controller.signal.aborted) setGuideError(errorMessage(reason)); }
    }
    void load().catch(reason => { if (active && !controller.signal.aborted) { setRecord(null); setError(errorMessage(reason)); } }).finally(() => { if (active) setLoading(false); }); return () => { active = false; controller.abort(); };
  }, [id, refresh]);
  useEffect(() => { const reset = () => { setGuide(null); setRefresh(value => value + 1); }; window.addEventListener('focus', reset); window.addEventListener('online', reset); return () => { window.removeEventListener('focus', reset); window.removeEventListener('online', reset); }; }, []);
  function go(value: number) { const next = new URLSearchParams(params); next.set('step', String(value + 1)); setParams(next); }
  function saved(value: Correction) { setRecord(value); setGuide(null); setRefresh(previous => previous + 1); }
  return <div className="correction-wizard"><PageHeader title={record?.data.title || 'Correct a submitted mistake'} description="Keep the original, check what should change, and prepare a correction you can take to the official route yourself." action={<Button variant="secondary" onClick={() => setRefresh(value => value + 1)}>Refresh saved correction</Button>} /><p><Link to={record ? `/app/cases/${record.id}` : '/app/cases'}>{record ? 'Open all case details and history' : 'Back to Paperwork cases'}</Link></p>
    {error && <Notice kind="error">{error}<Button variant="secondary" onClick={() => setRefresh(value => value + 1)}>Retry this correction</Button></Notice>}{loading && <p role="status">Opening the current correction. Your private entries are retained…</p>}
    {record && <>{record.data.cap_context?.fictional && <Notice kind="warning">Fictional example only. This is not your actual filing, deadline or authority response.</Notice>}<nav aria-label="Correction steps"><ol className="correction-steps">{names.map((name, index) => <li key={name}><button type="button" aria-current={step === index ? 'step' : undefined} onClick={() => go(index)}><span>{index + 1}</span>{name}</button></li>)}</ol></nav><p className="eyebrow">Step {step + 1} of 5 · application year {record.data.reporting_year}</p>{!canWrite && <Notice>Your current access is read-only. You can read the correction and its sources, but a farm owner or delegated reviewer must save changes.</Notice>}{record.data.focused_review_required !== true && <Notice>This earlier case has not enabled individual answer checks. Saving a guided details step explicitly enables them and requires a fresh review before sending.</Notice>}
      {step <= 2 && <DetailsStep key={`${record.id}/${step}`} record={record} step={step} canWrite={canWrite && !loading} onSaved={saved} onNext={() => go(step + 1)} />}
      {step === 2 && (guideError ? <Notice kind="error">{guideError}<Button variant="secondary" onClick={() => setRefresh(value => value + 1)}>Retry date guidance</Button></Notice> : guide ? <Guidance guide={guide} /> : <p role="status">The current correction guidance is not yet available. This is not permission to amend.</p>)}
      {step === 3 && !loading && <AnswerReview key={record.id} record={record} canWrite={canWrite} onSaved={saved} reload={() => setRefresh(value => value + 1)} />}
      {step === 4 && <section className="card"><h2>Prepare your folder</h2><p>The existing case review checks the current saved sources and every required answer check. A folder download never means anything was sent.</p><Notice>Read and resolve any remaining case checks. Unknown national rules or conditional guidance remain matters for the authority or adviser; an app review is not permission to change a filing.</Notice><p>The folder includes selected case documents, documents attached to completed items, and attachments selected in approved reports. Other private source files stay in your workspace.</p><Link className="button button-primary" to={`/app/cases/${record.id}#case-checks`}>Open final review and prepare the folder</Link><p>After you send the correction yourself, record what actually happened in the case. Keep a delivery receipt separate from an acceptance. Earlier sending records and their original selections remain in the history.</p><Link to={`/app/cases/${record.id}#case-delivery`}>Read sending, receipt and acceptance records</Link></section>}
      <div className="actions correction-step-navigation"><Button variant="secondary" disabled={step === 0} onClick={() => go(step - 1)}>Previous step</Button>{step < 4 && <Button variant="secondary" onClick={() => go(step + 1)}>Continue without changing saved details</Button>}</div>
    </>}
  </div>;
}
